import concurrent.futures
import time

class WorkflowEngine:
    def __init__(self):
        self.executor = concurrent.futures.ThreadPoolExecutor(max_workers=5)

    def start_timer(self, name, duration):
        print(f"Starting timer {name} for {duration} seconds")
        start_time = time.time()
        while time.time() - start_time < duration:
            time.sleep(1)
        print(f"Timer {name} has finished")

    def branch(self, condition, true_case, false_case):
        if condition:
            self.execute(true_case)
        else:
            self.execute(false_case)

    def loop(self, iterable, case):
        for item in iterable:
            self.execute(case)

    def execute(self, function):
        future = self.executor.submit(function)
        future.result()  # waits for the result

    def run_workflow(self, workflow):
        for step in workflow:
            if 'timer' in step:
                self.start_timer(**step)
            elif 'branch' in step:
                self.branch(**step)
            elif 'loop' in step:
                self.loop(**step)
            else:
                self.execute(step)
