        if item in self.stock:
            self.stock[item] += quantity
        else:
            self.stock[item] = quantity

        if supplier in self.suppliers:
            self.suppliers[supplier].append(item)
        else:
            self.suppliers[supplier] = [item]

    def log_changes(self, item, old_quantity, new_quantity):
        return f"{item} stock has been updated from {old_quantity} to {new_quantity}"

    def send_alert(self, item, quantity):
        if self.check_stock(item) < quantity:
            return f"{item} is running low. Only {self.check_stock(item)} items in stock."
